-- Isolated SQL contract fixture; production column types, no real student data.
create role anon; create role authenticated; create role service_role;
create schema auth; create schema private;
create function auth.uid() returns uuid language sql as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
create function private.normalize_assignment_answer(text) returns text language sql as $$ select lower(trim($1)) $$;
create function private.teacher_assignment_subject_key(text) returns text language sql as $$ select lower(trim($1)) $$;
create function public.is_superadmin(uuid) returns boolean language sql as $$ select false $$;
create function private.actor_has_feature_entitlement(text,boolean) returns boolean language sql as $$ select false $$;
create table public.assignment_questions (assignment_id uuid,
question_id uuid,
order_index integer,
